const fmtHora = (iso) => new Date(iso).toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo', hour: '2-digit', minute: '2-digit' });
return $input.all().map(({ json: item }) => {
  const texto = 'Comeca em breve: sessao de disputa do pregao que voce salvou.\n\n' +
    item.objeto.slice(0, 250) + (item.objeto.length > 250 ? '...' : '') + '\n\n' +
    'Orgao: ' + item.orgao + '\n' +
    'Abertura da sessao: ' + fmtHora(item.data_abertura_proposta) + '\n' +
    '\nEdital: ' + item.link;
  return { json: { ...item, numero: item.whatsapp_numero.replace(/\D/g, ''), texto } };
});
